widget.solution:
import math
import numpy as np

def train_test_backtest(y, x, split, entries):
    """Choose the entry with the best Sharpe on days before `split`; return (entry, train Sharpe, test Sharpe)."""
    best = None
    for e in entries:
        pnl = backtest(y, x, entry=e)[0]         # the reference backtest on every day
        tr, te = sharpe(pnl[:split]), sharpe(pnl[split:])
        if math.isnan(tr):
            continue
        if best is None or tr > best[1]:
            best = (e, tr, te)
    return best[0], round(best[1], 3), round(best[2], 3)


def sharpe(pnl):
    sd = np.std(pnl, ddof=1)
    return float("nan") if sd == 0 else float(np.mean(pnl) / sd * np.sqrt(252))


def is_tradable(report, max_half_life=30, alpha=0.05):
    """Both legs keep a unit root, Engle-Granger rejects, and the half-life is short enough."""
    return (report["adf_x"] > alpha and report["adf_y"] > alpha
            and report["eg_p"] < alpha and report["half_life"] <= max_half_life)
